WITH with_last AS (SELECT s.id, s.store_id, s.channel, s.amount, s.shipping_fee, x.payment_paid_at FROM orders s LEFT JOIN LATERAL (SELECT c.paid_at AS payment_paid_at FROM payments c WHERE c.order_id = s.id ORDER BY c.paid_at DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN shipping_fee >= 40 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count FROM with_last GROUP BY CASE WHEN shipping_fee >= 40 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY shipping_fee_tier NULLS LAST
